import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

/**
 * LineFillText
 * ────────────
 * Inline text filled with curved ribbons clipped to the letterforms.
 *
 * Paint order:
 *   1. Glyph silhouette
 *   2. `source-in` body color (`fillColor` or resolved `backgroundClassName`)
 *   3. `source-atop` horizontal beziers
 *
 * Coloring: pass a single-hue **alpha cascade** (1 → ~0.1) so dense rows read
 * as glowing stripes on a solid body — use `buildAlphaCascade()` to make one.
 *
 * Motion: shared-phase bows by default (classic single-arch look). Optional
 * `stagger` adds a light per-row lag. Auto-pauses off-screen / hidden;
 * reduced-motion freezes.
 */

import * as React from "react";
import { cn } from "@/lib/utils";

export interface LineFillTextProps {
  /** The string to clip the ribbons into. */
  text: string;
  /** Typography / layout classes (inherited by the measure node). */
  className?: string;
  /**
   * Tailwind background utilities resolved into the glyph body
   * (e.g. `"bg-[#b91c1c] dark:bg-[#7f1d1d]"`). Ignored when `fillColor` is set.
   */
  backgroundClassName?: string;
  /** Explicit glyph body fill. Wins over `backgroundClassName`. */
  fillColor?: string;
  /**
   * Ribbon palette. Best as a stepped-alpha cascade of one hue
   * (see `buildAlphaCascade`). Cycles by row.
   */
  colors?: string[];
  /** Seconds per full wave cycle. Default: 20. */
  duration?: number;
  /** Stroke width in CSS pixels. Default: 1.5. */
  lineWidth?: number;
  /** Vertical gap between ribbons in CSS pixels. Default: 4. */
  spacing?: number;
  /** Bezier bow depth in CSS pixels. Default: 60. */
  amplitude?: number;
  /**
   * Per-row phase lag (0–1). 0 = every row shares one arch (Aceternity look).
   * Default: 0.
   */
  stagger?: number;
  /** Absolutely fill the parent. Default: false. */
  overlay?: boolean;
  /** Force paused. When omitted, auto-pauses off-screen / hidden. */
  paused?: boolean;
}

type Engine = {
  width: number;
  height: number;
  dpr: number;
  baselineY: number;
  font: string;
  fillColor: string;
  colors: string[];
  spacing: number;
  amplitude: number;
  duration: number;
  lineWidth: number;
  stagger: number;
  reducedMotion: boolean;
  startTime: number;
  ctx: CanvasRenderingContext2D;
};

/**
 * Build a single-hue ribbon palette: full opacity → faint.
 * This is the coloring style that makes dense fills read as glowing stripes.
 */
export function buildAlphaCascade(
  rgb: readonly [number, number, number],
  steps = 10,
): string[] {
  const n = Math.max(2, Math.round(steps));
  const [r, g, b] = rgb;
  const out: string[] = [];
  for (let i = 0; i < n; i++) {
    const alpha = Number((1 - i / n).toFixed(3));
    // Keep a floor so the faintest stop still reads on dark bodies.
    out.push(`rgba(${r}, ${g}, ${b}, ${Math.max(0.08, alpha)})`);
  }
  return out;
}

function rgbToHsl(
  r: number,
  g: number,
  b: number,
): [number, number, number] {
  const rn = r / 255;
  const gn = g / 255;
  const bn = b / 255;
  const max = Math.max(rn, gn, bn);
  const min = Math.min(rn, gn, bn);
  const l = (max + min) / 2;
  if (max === min) return [0, 0, l];
  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h = 0;
  if (max === rn) h = ((gn - bn) / d + (gn < bn ? 6 : 0)) / 6;
  else if (max === gn) h = ((bn - rn) / d + 2) / 6;
  else h = ((rn - gn) / d + 4) / 6;
  return [h, s, l];
}

function hslToRgb(h: number, s: number, l: number): [number, number, number] {
  if (s === 0) {
    const v = Math.round(l * 255);
    return [v, v, v];
  }
  const hue2rgb = (p: number, q: number, t: number) => {
    let tt = t;
    if (tt < 0) tt += 1;
    if (tt > 1) tt -= 1;
    if (tt < 1 / 6) return p + (q - p) * 6 * tt;
    if (tt < 1 / 2) return q;
    if (tt < 2 / 3) return p + (q - p) * (2 / 3 - tt) * 6;
    return p;
  };
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  return [
    Math.round(hue2rgb(p, q, h + 1 / 3) * 255),
    Math.round(hue2rgb(p, q, h) * 255),
    Math.round(hue2rgb(p, q, h - 1 / 3) * 255),
  ];
}

/**
 * Solid body under the cascade. Must be clearly darker than the ribbon hue
 * or the alpha strips disappear. Light mode stays at ~600-level saturation;
 * dark mode drops deeper so stripes still read on dark canvases.
 * Near-white ribbons get a zinc body.
 */
export function bodyFillFromRibbon(
  rgb: readonly [number, number, number],
  mode: "light" | "dark" = "dark",
): string {
  // Signal pairing matches Aceternity: blue-600 light / blue-700 dark.
  if (rgb[0] === 0 && rgb[1] === 153 && rgb[2] === 255) {
    return mode === "light" ? "#2563eb" : "#1d4ed8";
  }

  const [h, s, l] = rgbToHsl(rgb[0], rgb[1], rgb[2]);
  if (l > 0.82 || s < 0.08) {
    return mode === "light" ? "#3f3f46" : "#27272a";
  }

  const bodyL =
    mode === "light"
      ? Math.min(0.42, Math.max(0.32, l * 0.7))
      : Math.min(0.3, Math.max(0.2, l * 0.48));
  const bodyS = Math.min(0.95, Math.max(0.55, s * 0.92));
  const [br, bg, bb] = hslToRgb(h, bodyS, bodyL);
  return `rgb(${br}, ${bg}, ${bb})`;
}

/** Ribbon hue → darker body + alpha cascade (playground / presets). */
export function styleFromRibbonHue(
  rgb: readonly [number, number, number],
  steps = 10,
  mode: "light" | "dark" = "dark",
): { fillColor: string; colors: string[] } {
  return {
    fillColor: bodyFillFromRibbon(rgb, mode),
    colors: buildAlphaCascade(rgb, steps),
  };
}

const DEFAULT_COLORS = buildAlphaCascade([255, 0, 0], 10);
/** Theme-aware chili body — light stays vivid, dark goes deep. */
const DEFAULT_BG_CLASS = "bg-[#b91c1c] dark:bg-[#7f1d1d]";
const RESIZE_DEBOUNCE_MS = 50;

/**
 * Ribbon-filled inline text. Alpha-cascade strokes clipped inside the glyphs.
 */
export function LineFillText({
  text,
  className = "",
  backgroundClassName = DEFAULT_BG_CLASS,
  fillColor,
  colors = DEFAULT_COLORS,
  duration = 20,
  lineWidth = 1.5,
  spacing = 4,
  amplitude = 60,
  stagger = 0,
  overlay = false,
  paused,
}: LineFillTextProps) {
  const wrapRef = React.useRef<HTMLSpanElement | null>(null);
  const measureRef = React.useRef<HTMLSpanElement | null>(null);
  const bgRef = React.useRef<HTMLSpanElement | null>(null);
  const canvasRef = React.useRef<HTMLCanvasElement | null>(null);
  const engineRef = React.useRef<Engine | null>(null);
  const rafRef = React.useRef<number>(0);
  const resizeTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  const inViewRef = React.useRef(true);
  const pageVisibleRef = React.useRef(true);
  const pausedPropRef = React.useRef(paused);
  const fillPropRef = React.useRef(fillColor);
  const colorsPropRef = React.useRef(colors);
  const textRef = React.useRef(text);
  const kickLoopRef = React.useRef<(() => void) | null>(null);

  pausedPropRef.current = paused;
  fillPropRef.current = fillColor;
  colorsPropRef.current = colors;
  textRef.current = text;

  const safeDuration = Math.max(0.5, duration);
  const safeSpacing = Math.max(2, spacing);
  const safeAmplitude = Math.max(0, amplitude);
  const safeLineWidth = Math.max(0.4, lineWidth);
  const safeStagger = Math.min(1, Math.max(0, stagger));

  const liveRef = React.useRef({
    duration: safeDuration,
    spacing: safeSpacing,
    amplitude: safeAmplitude,
    lineWidth: safeLineWidth,
    stagger: safeStagger,
  });
  liveRef.current = {
    duration: safeDuration,
    spacing: safeSpacing,
    amplitude: safeAmplitude,
    lineWidth: safeLineWidth,
    stagger: safeStagger,
  };

  const resolveBodyColor = React.useCallback((): string => {
    if (fillPropRef.current && fillPropRef.current.trim()) {
      return fillPropRef.current.trim();
    }
    const bg = bgRef.current;
    if (bg) {
      const computed = getComputedStyle(bg).backgroundColor;
      if (
        computed &&
        computed !== "rgba(0, 0, 0, 0)" &&
        computed !== "transparent"
      ) {
        return computed;
      }
    }
    return document.documentElement.classList.contains("dark")
      ? "#7f1d1d"
      : "#b91c1c";
  }, []);

  const resolveLineColors = React.useCallback((): string[] => {
    const list = colorsPropRef.current;
    if (!list || list.length === 0) {
      return DEFAULT_COLORS.map(resolveCssColor);
    }
    return list.map(resolveCssColor);
  }, []);

  const rebuild = React.useCallback(() => {
    const measure = measureRef.current;
    const canvas = canvasRef.current;
    if (!measure || !canvas) return;

    const label = textRef.current || " ";
    const computed = getComputedStyle(measure);
    const font = [
      computed.fontStyle,
      computed.fontWeight,
      computed.fontSize,
      computed.fontFamily,
    ]
      .filter(Boolean)
      .join(" ");
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = measure.getBoundingClientRect();

    const prev = engineRef.current;
    const ctx = prev?.ctx ?? canvas.getContext("2d", { alpha: true });
    if (!ctx) return;

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.font = font;
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    const metrics = ctx.measureText(label);
    const ascent =
      metrics.fontBoundingBoxAscent ||
      metrics.actualBoundingBoxAscent ||
      parseFloat(computed.fontSize) * 0.8;
    const descent =
      metrics.fontBoundingBoxDescent ||
      metrics.actualBoundingBoxDescent ||
      parseFloat(computed.fontSize) * 0.2;
    const padTop = parseFloat(computed.paddingTop) || 0;
    const padBottom = parseFloat(computed.paddingBottom) || 0;
    // Prefer the padded measure box; never go shorter than full font ink.
    const cssW = Math.max(
      1,
      Math.ceil(Math.max(rect.width, metrics.width)),
    );
    const cssH = Math.max(
      1,
      Math.ceil(Math.max(rect.height, ascent + descent + padTop + padBottom)),
    );
    // Match CSS: padding-top, then alphabetic baseline of the em box.
    const baselineY = padTop + ascent;
    const pixelW = Math.max(1, Math.round(cssW * dpr));
    const pixelH = Math.max(1, Math.round(cssH * dpr));

    if (canvas.width !== pixelW) canvas.width = pixelW;
    if (canvas.height !== pixelH) canvas.height = pixelH;
    canvas.style.width = `${cssW}px`;
    canvas.style.height = `${cssH}px`;

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.font = font;
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;

    const live = liveRef.current;
    const now = performance.now();
    engineRef.current = {
      width: cssW,
      height: cssH,
      dpr,
      baselineY,
      font,
      fillColor: resolveBodyColor(),
      colors: resolveLineColors(),
      spacing: live.spacing,
      amplitude: live.amplitude,
      duration: live.duration,
      lineWidth: live.lineWidth,
      stagger: live.stagger,
      reducedMotion,
      startTime: prev?.startTime ?? now,
      ctx,
    };

    paintFrame(engineRef.current, label, now);
    kickLoopRef.current?.();
  }, [resolveBodyColor, resolveLineColors]);

  const syncColors = React.useCallback(() => {
    const engine = engineRef.current;
    if (!engine) return;
    engine.fillColor = resolveBodyColor();
    engine.colors = resolveLineColors();
    paintFrame(engine, textRef.current, performance.now());
  }, [resolveBodyColor, resolveLineColors]);

  React.useEffect(() => {
    const engine = engineRef.current;
    if (!engine) return;
    const live = liveRef.current;
    engine.spacing = live.spacing;
    engine.amplitude = live.amplitude;
    engine.duration = live.duration;
    engine.lineWidth = live.lineWidth;
    engine.stagger = live.stagger;
    paintFrame(engine, textRef.current, performance.now());
    kickLoopRef.current?.();
  }, [
    safeSpacing,
    safeAmplitude,
    safeDuration,
    safeLineWidth,
    safeStagger,
  ]);

  React.useEffect(() => {
    rebuild();
  }, [text, rebuild]);

  React.useEffect(() => {
    const measure = measureRef.current;
    if (!measure) return;

    const scheduleRebuild = () => {
      if (resizeTimerRef.current) clearTimeout(resizeTimerRef.current);
      resizeTimerRef.current = setTimeout(() => {
        resizeTimerRef.current = null;
        rebuild();
      }, RESIZE_DEBOUNCE_MS);
    };

    const ro = new ResizeObserver(scheduleRebuild);
    ro.observe(measure);

    const mo = new MutationObserver(() => {
      // Theme toggles swap `dark:` body fills — debounce with resize.
      scheduleRebuild();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme"],
    });

    return () => {
      ro.disconnect();
      mo.disconnect();
      if (resizeTimerRef.current) clearTimeout(resizeTimerRef.current);
    };
  }, [rebuild, backgroundClassName]);

  React.useEffect(() => {
    syncColors();
  }, [fillColor, colors, syncColors]);

  React.useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;

    let running = false;

    const shouldRun = () => {
      const engine = engineRef.current;
      if (!engine || engine.reducedMotion) return false;
      if (pausedPropRef.current === true) return false;
      if (pausedPropRef.current === false) return true;
      return inViewRef.current && pageVisibleRef.current;
    };

    const tick = (now: number) => {
      const engine = engineRef.current;
      if (!engine || !shouldRun()) {
        running = false;
        if (engine) paintFrame(engine, textRef.current, now);
        return;
      }
      paintFrame(engine, textRef.current, now);
      rafRef.current = requestAnimationFrame(tick);
    };

    const ensureLoop = () => {
      const engine = engineRef.current;
      if (!engine || engine.reducedMotion) return;
      if (pausedPropRef.current === true) return;
      if (
        pausedPropRef.current !== false &&
        !(inViewRef.current && pageVisibleRef.current)
      ) {
        return;
      }
      if (running) return;
      engine.startTime = performance.now();
      running = true;
      rafRef.current = requestAnimationFrame(tick);
    };
    kickLoopRef.current = ensureLoop;

    const io = new IntersectionObserver(
      (entries) => {
        inViewRef.current = entries.some((e) => e.isIntersecting);
        if (inViewRef.current) ensureLoop();
      },
      { threshold: 0.01 },
    );
    io.observe(wrap);

    const onVisibility = () => {
      pageVisibleRef.current = document.visibilityState !== "hidden";
      if (pageVisibleRef.current) ensureLoop();
    };
    document.addEventListener("visibilitychange", onVisibility);
    pageVisibleRef.current = document.visibilityState !== "hidden";

    ensureLoop();

    return () => {
      running = false;
      kickLoopRef.current = null;
      cancelAnimationFrame(rafRef.current);
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [paused]);

  return (
    <span
      ref={wrapRef}
      className={cn(
        "relative inline-block align-baseline leading-none overflow-visible",
        overlay && "absolute inset-0",
        className,
      )}
    >
      <span
        ref={bgRef}
        className={cn(
          "pointer-events-none absolute h-0 w-0 opacity-0",
          backgroundClassName,
        )}
        aria-hidden
      />
      {/*
        Measure drives width + CSS baseline. Extra bottom padding so bold glyph
        ink isn’t clipped by leading-none; canvas height matches in rebuild().
      */}
      <span
        ref={measureRef}
        className="invisible inline-block leading-none pt-[0.06em] pb-[0.22em]"
        aria-hidden
      >
        {text || " "}
      </span>
      <canvas
        ref={canvasRef}
        className="pointer-events-none absolute top-0 left-0 [transform:translateZ(0)]"
        aria-label={text}
        role="img"
      />
    </span>
  );
}

function resolveCssColor(color: string): string {
  const trimmed = color.trim();
  if (!trimmed.startsWith("var(")) return trimmed;
  const varName = trimmed.slice(4, -1).trim();
  const resolved = getComputedStyle(document.documentElement)
    .getPropertyValue(varName)
    .trim();
  return resolved || trimmed;
}

function paintFrame(engine: Engine, text: string, now: number) {
  const {
    ctx,
    dpr,
    width,
    height,
    baselineY,
    font,
    fillColor,
    colors,
    spacing,
    amplitude,
    duration,
    lineWidth,
    stagger,
    reducedMotion,
    startTime,
  } = engine;

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);

  ctx.globalCompositeOperation = "source-over";
  ctx.font = font;
  ctx.textBaseline = "alphabetic";
  ctx.textAlign = "left";
  ctx.fillStyle = "#000";
  ctx.fillText(text || " ", 0, baselineY);

  ctx.globalCompositeOperation = "source-in";
  ctx.fillStyle = fillColor;
  ctx.fillRect(0, 0, width, height);

  ctx.globalCompositeOperation = "source-atop";
  ctx.lineWidth = lineWidth;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  const elapsed = reducedMotion ? 0 : Math.max(0, (now - startTime) / 1000);
  const phase = (elapsed / Math.max(0.001, duration)) * Math.PI * 2;
  // Spare rows cover amplitude overshoot (matches Aceternity +10 density).
  const spare = Math.max(10, Math.ceil((amplitude * 1.2) / spacing) + 2);
  const numLines = Math.floor(height / spacing) + spare;
  const paletteLen = Math.max(1, colors.length);
  const lagStep = stagger * 0.35;
  const c1 = width * 0.33;
  const c2 = width * 0.66;
  const shared = lagStep === 0;
  const sharedCurve1 = shared ? Math.sin(phase) * amplitude : 0;
  const sharedCurve2 = shared ? Math.sin(phase + 0.5) * amplitude * 0.6 : 0;

  for (let i = 0; i < numLines; i++) {
    const y = i * spacing;
    let curve1: number;
    let curve2: number;
    if (shared) {
      curve1 = sharedCurve1;
      curve2 = sharedCurve2;
    } else {
      const rowPhase = phase - i * lagStep;
      curve1 = Math.sin(rowPhase) * amplitude;
      curve2 = Math.sin(rowPhase + 0.5) * amplitude * 0.6;
    }

    ctx.strokeStyle = colors[i % paletteLen]!;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.bezierCurveTo(c1, y + curve1, c2, y + curve2, width, y);
    ctx.stroke();
  }

  ctx.globalCompositeOperation = "source-over";
}
